I have designed this to be **production-ready**, handling loading states, error handling, and the specific nuances of the `@apollo/client` library (the industry standard for React GraphQL).

### The `onSubmit` Function

```javascript
import { useMutation } from '@apollo/client';
import { toast } from 'react-toastify'; // Optional: for user feedback

// 1. Define the mutation query
const CREATE_USER_MUTATION = `
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      createdAt
    }
  }
`;

// 2. The onSubmit function
const handleFormSubmit = async (e, variables) => {
  e.preventDefault(); // Stop default form submission (page reload)

  try {
    // Check if variables are valid
    if (!variables) {
      throw new Error("Form data is missing.");
    }

    // Execute the mutation
    const { data, error } = await useMutation(CREATE_USER_MUTATION, {
      variables: { input: variables }
    });

    if (error) {
      throw error;
    }

    // Success Logic
    console.log('Success:', data);
    toast.success("User created successfully!");

    // Reset form or redirect
    // e.target.reset(); 
    // navigate('/dashboard');

  } catch (err) {
    // Error Logic
    console.error('GraphQL Error:', err);
    toast.error(err.message || "Something went wrong.");
  }
};
