Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), concatenate them into a 7-bit integer, and write that integer into the `Uint8Array` at the current offset. We then advance the offset by 1 byte (8 bits).
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits as the `id` and the upper 3 bits as the `size`.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array.
 * 
 * @param {Array} entities - Array of objects with { id, size }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
    if (!entities || entities.length === 0) {
        return new Uint8Array(0);
    }

    // Calculate total size: 1 byte per entity (4 bits + 3 bits = 7 bits, rounded up to 8)
    const totalSize = entities.length; 
    const buffer = new Uint8Array(totalSize);
    let offset = 0;

    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];

        // Combine id (4 bits) and size (3 bits) into a single 7-bit integer
        // (id << 3) moves id to the upper bits, size stays in lower bits
        const packedValue = (entity.id << 3) | entity.size;

        // Write the byte to the buffer
        buffer[offset] = packedValue;

        // Advance offset by 1 byte
        offset++;
    }

    return buffer;
}

/**
 * Unpacks a Uint8Array into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id, size }
 */
function unpackEntities(buffer) {
    const entities = [];

    for (let i = 0; i < buffer.length; i++) {
        const byte = buffer[i];

        // Extract id (lower 4 bits)
        const id = byte & 0x0F; 

        // Extract size (upper 3 bits)
        // (byte >> 3) shifts the byte right by 3 positions
        const size = byte >> 3;

        entities.push({ id, size });
    }

    return entities;
}

// --- Example Usage ---

const entities = [
    { id: 0, size: 0 }, // 0000 0000
    { id: 1, size: 1 }, // 0001 0001
    { id: 15, size: 7 } // 1111 1111 (Max values)
];

// Pack
const packed = packEntities(entities);
console.log("Packed Buffer:", packed); // Uint8Array [ 0, 17, 255 ]

// Unpack
const unpacked = unpackEntities(packed);
console.log("Unpacked Entities:", unpacked);
