        DialogueNode option2 = new DialogueNode("You go right.", null);
        DialogueNode option3 = new DialogueNode("You stay here.", null);

        // Create the main node
        DialogueNode startNode = new DialogueNode(
            "You stand at a crossroads. Where do you go?", 
            new DialogueNode[]{option1, option2, option3}
        );

        startNode.display(scanner);
    }
}
